// AGENTE ANÁLISIS TÉCNICO — DeepSeek V3 + indicadores locales
const cfg = $('Config').first().json;
const raw = $('Market Data').first().json;
const klines = Array.isArray(raw) ? raw : [];
const closes = klines.map(k => parseFloat(k[4]));
const highs  = klines.map(k => parseFloat(k[2]));
const lows   = klines.map(k => parseFloat(k[3]));
const vols   = klines.map(k => parseFloat(k[5]));
const price  = closes.at(-1) || 0;

// Indicadores
const sma = (arr, n) => arr.length < n ? null : arr.slice(-n).reduce((a,b)=>a+b,0)/n;
const ema = (arr, n) => {
  let k = 2/(n+1), e = arr[0];
  for(let i=1;i<arr.length;i++) e = arr[i]*k + e*(1-k);
  return e;
};
const rsiCalc = (arr, n=14) => {
  let g=0,l=0;
  for(let i=arr.length-n;i<arr.length;i++){const d=arr[i]-arr[i-1]; d>0?g+=d:l-=d;}
  return 100-100/(1+(g/n)/((l/n)||0.001));
};

const sma20  = sma(closes, 20);
const sma50  = sma(closes, 50);
const sma200 = sma(closes, Math.min(200,closes.length));
const ema12  = ema(closes, 12);
const ema26  = ema(closes, 26);
const macd   = ema12 - ema26;
const rsi    = rsiCalc(closes);
const vol24  = vols.slice(-24).reduce((a,b)=>a+b,0);
const volAvg = vols.slice(-50).reduce((a,b)=>a+b,0)/50;
const volRatio = vol24/((volAvg*24)||1);

// Señal local
let signal='HOLD', confidence=0.5;
if(price>sma20 && sma20>sma50 && rsi<70 && macd>0){signal='BUY'; confidence=0.65+(rsi<60?.05:0)+(volRatio>1.2?.05:0);}
else if(price<sma20 && sma20<sma50 && rsi>30 && macd<0){signal='SELL'; confidence=0.65+(rsi>40?.05:0)+(volRatio>1.2?.05:0);}

let summary = `Precio $${price.toFixed(2)} | SMA20=${sma20?.toFixed(0)} SMA50=${sma50?.toFixed(0)} | RSI=${rsi.toFixed(1)} | MACD=${macd.toFixed(2)} | Vol ratio=${volRatio.toFixed(2)}`;

try {
  const res = await fetch('https://api.deepseek.com/v1/chat/completions', {
    method:'POST',
    headers:{'Authorization':`Bearer ${$env.DEEPSEEK_API_KEY}`,'Content-Type':'application/json'},
    body: JSON.stringify({
      model:'deepseek-chat',
      messages:[{role:'user',content:`Eres AGENTE ANÁLISIS TÉCNICO crypto experto. Símbolo: ${cfg.symbol} precio $${price.toFixed(2)}. Indicadores: SMA20=${sma20?.toFixed(0)}, SMA50=${sma50?.toFixed(0)}, SMA200=${sma200?.toFixed(0)}, RSI=${rsi.toFixed(1)}, MACD=${macd.toFixed(4)}, Volumen ratio=${volRatio.toFixed(2)}. Señal preliminar: ${signal}. Analiza y confirma. Responde SOLO en JSON: {"signal":"BUY|SELL|HOLD","confidence":0.0-1.0,"summary":"texto","support":numero,"resistance":numero}`}],
      max_tokens:400,temperature:0.1,response_format:{type:'json_object'}
    })
  });
  const d = await res.json();
  const ai = JSON.parse(d.choices[0].message.content);
  signal=ai.signal||signal; confidence=ai.confidence||confidence; summary=ai.summary||summary;
} catch(e) { summary += ` [IA no disponible: ${e.message}]`; }

return [{json:{agent:'ANÁLISIS_TÉCNICO',model:'DeepSeek-V3 + indicadores',signal,confidence,summary,indicators:{price,sma20,sma50,sma200,rsi,macd,volRatio}}}];

// AGENTE ANÁLISIS FUNDAMENTAL — Claude Opus 4.6
const cfg   = $('Config').first().json;
const raw   = $('Market Data').first().json;
const klines = Array.isArray(raw) ? raw : [];
const price = parseFloat(klines.at(-1)?.[4] || 0);
const name  = cfg.symbol.replace('USDT','').replace('BTC','Bitcoin').replace('ETH','Ethereum');

const prompt = `Eres AGENTE ANÁLISIS FUNDAMENTAL experto en criptoactivos.\n\nActivo: ${name} (${cfg.symbol}) — Precio actual: $${price.toFixed(2)}\n\nAnaliza considerando:\n1. Capitalización de mercado y posición competitiva\n2. Utilidad real y adopción del protocolo\n3. Actividad de desarrollo (commits, actualizaciones)\n4. Adopción institucional y flujos de capital\n5. Ciclo macro: tasas de interés, DXY, correlación con mercados tradicionales\n6. Contexto regulatorio global\n7. Métricas on-chain relevantes\n\nResponde SOLO en JSON:\n{"signal":"BUY|SELL|HOLD","confidence":0.0-1.0,"summary":"2-3 oraciones","catalysts":["..."],"risks":["..."],"macro_bias":"BULLISH|BEARISH|NEUTRAL"}`;

let result = {signal:'HOLD',confidence:0.5,summary:'API Anthropic no disponible',catalysts:[],risks:[],macro_bias:'NEUTRAL'};
try {
  const res = await fetch('https://api.anthropic.com/v1/messages', {
    method:'POST',
    headers:{'x-api-key':$env.ANTHROPIC_API_KEY,'anthropic-version':'2023-06-01','Content-Type':'application/json'},
    body: JSON.stringify({model:'claude-opus-4-6',max_tokens:600,messages:[{role:'user',content:prompt}]})
  });
  const d = await res.json();
  const text = d.content[0].text;
  const m = text.match(/\{[\s\S]*\}/);
  if(m) result = JSON.parse(m[0]);
} catch(e) { result.summary = `Error: ${e.message}`; }

return [{json:{agent:'ANÁLISIS_FUNDAMENTAL',model:'Claude Opus 4.6',...result}}];

// AGENTE SENTIMIENTO MERCADO — DeepSeek + FinBERT approach + NewsAPI
const cfg      = $('Config').first().json;
const newsRaw  = $('News Data').first().json;
const articles = newsRaw?.articles || [];
const headlines = articles.slice(0,15).map(a=>`- ${a.title} (${a.source?.name||'?'})`).join('\n') || 'Sin noticias disponibles';

const prompt = `Eres AGENTE SENTIMIENTO DE MERCADO especializado en crypto.\n\nSímbolo: ${cfg.symbol}\n\nNoticias recientes (${articles.length} artículos):\n${headlines}\n\nAnaliza el sentimiento general del mercado para este activo considerando:\n- Tono de noticias (positivo/negativo/neutro)\n- Eventos macro relevantes\n- Narrativas dominantes en la comunidad\n- Fear & Greed implícito\n- Riesgo de volatilidad por noticias\n\nResponde SOLO en JSON:\n{"signal":"BUY|SELL|HOLD","confidence":0.0-1.0,"sentiment_score":-1.0-1.0,"summary":"texto","dominant_narratives":["..."],"fear_greed":"EXTREME_FEAR|FEAR|NEUTRAL|GREED|EXTREME_GREED","news_risk":"LOW|MEDIUM|HIGH"}`;

let result = {signal:'HOLD',confidence:0.5,sentiment_score:0,summary:'API no disponible',dominant_narratives:[],fear_greed:'NEUTRAL',news_risk:'MEDIUM'};
try {
  const res = await fetch('https://api.deepseek.com/v1/chat/completions', {
    method:'POST',
    headers:{'Authorization':`Bearer ${$env.DEEPSEEK_API_KEY}`,'Content-Type':'application/json'},
    body: JSON.stringify({
      model:'deepseek-chat',
      messages:[{role:'user',content:prompt}],
      max_tokens:500,temperature:0.2,response_format:{type:'json_object'}
    })
  });
  const d = await res.json();
  result = JSON.parse(d.choices[0].message.content);
} catch(e) { result.summary = `Error: ${e.message}`; }

return [{json:{agent:'SENTIMIENTO_MERCADO',model:'DeepSeek-V3 + NewsAPI',...result,articles_analyzed:articles.length}}];

// AGENTE EVALUACIÓN RIESGO — DeepSeek R1
const cfg = $('Config').first().json;
const items = $input.all().map(i=>i.json);

// Indexar agentes
const agents = {};
for(const r of items) if(r.agent) agents[r.agent] = r;

// Estadísticas de votos
const signals = items.filter(r=>r.signal&&r.confidence);
const bySignal = {BUY:0,SELL:0,HOLD:0};
let weightedConf = 0, totalW = 0;
for(const s of signals){
  bySignal[s.signal] = (bySignal[s.signal]||0)+1;
  weightedConf += (s.confidence||0);
  totalW++;
}
const avgConf = totalW>0 ? weightedConf/totalW : 0;
const dominant = Object.entries(bySignal).sort((a,b)=>b[1]-a[1])[0][0];

const prompt = `Eres AGENTE EVALUACIÓN DE RIESGO para trading algorítmico de crypto.\n\nConsenso de agentes:\n${JSON.stringify(signals.map(s=>({agente:s.agent,señal:s.signal,confianza:s.confidence})),null,2)}\n\nVotos: BUY=${bySignal.BUY} SELL=${bySignal.SELL} HOLD=${bySignal.HOLD}\nConfianza promedio: ${avgConf.toFixed(3)}\nSeñal dominante: ${dominant}\n\nParámetros de riesgo configurados:\n- Posición máxima: $${cfg.risk_max_position_usd}\n- Drawdown máximo: ${cfg.risk_max_drawdown_pct}%\n- Umbral de confianza: ${cfg.confidence_threshold}\n\nEvalúa si proceder. Si la confianza promedio < ${cfg.confidence_threshold}, rechaza.\nCalcula el tamaño de posición apropiado considerando el riesgo.\n\nResponde SOLO en JSON:\n{"approved":true|false,"risk_level":"LOW|MEDIUM|HIGH|CRITICAL","position_size_usd":0,"reason":"texto","warnings":["..."],"max_loss_usd":0}`;

let risk = {approved:false,risk_level:'HIGH',position_size_usd:0,reason:'API no disponible',warnings:[],max_loss_usd:0};
try {
  const res = await fetch('https://api.deepseek.com/v1/chat/completions', {
    method:'POST',
    headers:{'Authorization':`Bearer ${$env.DEEPSEEK_API_KEY}`,'Content-Type':'application/json'},
    body: JSON.stringify({
      model:'deepseek-reasoner',
      messages:[{role:'user',content:prompt}],
      max_tokens:700,temperature:0
    })
  });
  const d = await res.json();
  const text = d.choices[0].message.content;
  const m = text.match(/\{[\s\S]*\}/);
  if(m) risk = JSON.parse(m[0]);
} catch(e) { risk.reason = `Error: ${e.message}`; }

// Hard overrides de seguridad
if(avgConf < cfg.confidence_threshold){
  risk.approved = false;
  risk.warnings = [...(risk.warnings||[]), `Confianza ${avgConf.toFixed(2)} < umbral ${cfg.confidence_threshold}`];
}
if((risk.position_size_usd||0) > cfg.risk_max_position_usd){
  risk.position_size_usd = cfg.risk_max_position_usd;
  risk.warnings = [...(risk.warnings||[]), `Posición recortada al máximo $${cfg.risk_max_position_usd}`];
}

return [{json:{agent:'EVALUACIÓN_RIESGO',model:'DeepSeek-R1',...risk,vote_summary:{buyVotes:bySignal.BUY,sellVotes:bySignal.SELL,holdVotes:bySignal.HOLD,avgConf:parseFloat(avgConf.toFixed(3)),dominant},all_agents:agents,config:cfg}}];

// AGENTE ESTRATEGIA — Claude Sonnet 4.6
const risk    = $input.first().json;
const cfg     = risk.config || {};
const agents  = risk.all_agents || {};
const tech    = agents['ANÁLISIS_TÉCNICO'] || {};
const fund    = agents['ANÁLISIS_FUNDAMENTAL'] || {};
const sent    = agents['SENTIMIENTO_MERCADO'] || {};

const prompt = `Eres AGENTE DE ESTRATEGIA de trading — defines la estrategia de ejecución concreta.\n\nSímbolo: ${cfg.symbol}\nModo: ${cfg.dry_run?'SIMULACIÓN (DRY RUN)':'PRODUCCIÓN — operación real'}\n\nResumen de análisis:\n- Técnico (${tech.signal}, confianza ${tech.confidence}): ${tech.summary}\n- Fundamental (${fund.signal}, confianza ${fund.confidence}): ${fund.summary}\n- Sentimiento (${sent.signal}, confianza ${sent.confidence}): ${sent.summary}\n\nEvaluación de riesgo: ${risk.approved?'APROBADO':'RECHAZADO'} — Nivel: ${risk.risk_level}\nPresupuesto aprobado: $${risk.position_size_usd}\nRazón de riesgo: ${risk.reason}\n\nPrecio actual estimado: $${tech.indicators?.price||0}\nSoporte: ${tech.indicators?.sma50||0} | Resistencia: ${tech.indicators?.sma20||0}\n\nDefine la estrategia óptima. Si el riesgo NO fue aprobado, la acción debe ser HOLD.\n\nResponde SOLO en JSON:\n{"action":"BUY|SELL|HOLD","order_type":"MARKET|LIMIT","entry_price":0,"stop_loss":0,"take_profit":0,"risk_reward_ratio":0,"position_size_usd":0,"strategy_name":"nombre","rationale":"texto"}`;

let strat = {action:'HOLD',order_type:'MARKET',entry_price:tech.indicators?.price||0,stop_loss:0,take_profit:0,risk_reward_ratio:0,position_size_usd:0,strategy_name:'Sin estrategia',rationale:'API no disponible'};
try {
  const res = await fetch('https://api.anthropic.com/v1/messages', {
    method:'POST',
    headers:{'x-api-key':$env.ANTHROPIC_API_KEY,'anthropic-version':'2023-06-01','Content-Type':'application/json'},
    body: JSON.stringify({model:'claude-sonnet-4-6',max_tokens:700,messages:[{role:'user',content:prompt}]})
  });
  const d = await res.json();
  const text = d.content[0].text;
  const m = text.match(/\{[\s\S]*\}/);
  if(m) strat = JSON.parse(m[0]);
} catch(e) { strat.rationale = `Error: ${e.message}`; }

// Safety: override si riesgo rechazado
if(!risk.approved){ strat.action='HOLD'; strat.rationale=`Riesgo rechazado: ${risk.reason}`; }
if((strat.position_size_usd||0) > (risk.position_size_usd||0)) strat.position_size_usd = risk.position_size_usd;

return [{json:{agent:'ESTRATEGIA',model:'Claude Sonnet 4.6',...strat,risk_approved:risk.approved,risk_level:risk.risk_level,risk_warnings:risk.warnings,vote_summary:risk.vote_summary,all_agents:agents,config:cfg}}];

// AGENTE DECISIÓN FINAL — ASESOR DE TRADING — Claude Opus 4.6
const strat  = $input.first().json;
const cfg    = strat.config || {};
const agents = strat.all_agents || {};

const prompt = `Eres el ASESOR DE TRADING — agente de decisión final con máxima autoridad.\n\nTu trabajo: revisar todo el análisis y tomar la decisión definitiva de operación.\nPuedes confirmar, modificar o vetar cualquier propuesta anterior.\n\nSímbolo: ${cfg.symbol} | Modo: ${cfg.dry_run?'SIMULACIÓN':'PRODUCCIÓN'}\n\n=== ESTRATEGIA PROPUESTA ===\nAcción: ${strat.action} | Tipo orden: ${strat.order_type}\nEntrada: $${strat.entry_price} | SL: $${strat.stop_loss} | TP: $${strat.take_profit}\nTamaño: $${strat.position_size_usd} | R:R = ${strat.risk_reward_ratio}\nEstrategia: ${strat.strategy_name}\nRationale: ${strat.rationale}\n\n=== CONTEXTO DE AGENTES ===\nTécnico: ${agents.ANÁLISIS_TÉCNICO?.summary}\nFundamental: ${agents.ANÁLISIS_FUNDAMENTAL?.summary}\nSentimiento: ${agents.SENTIMIENTO_MERCADO?.summary}\nVotos: ${JSON.stringify(strat.vote_summary)}\n\n=== RIESGO ===\nAprobado: ${strat.risk_approved} | Nivel: ${strat.risk_level}\nAdvertencias: ${JSON.stringify(strat.risk_warnings)}\n\nDECIDES TÚ. Si todo es coherente, confirma. Si detectas inconsistencias o riesgo excesivo, corrige o cancela.\nEl campo dry_run DEBE ser ${cfg.dry_run} (no lo cambies).\n\nResponde SOLO en JSON:\n{"decision":"BUY|SELL|HOLD","final_action":{"type":"MARKET|LIMIT","symbol":"${cfg.symbol}","side":"buy|sell|none","quantity_usd":0,"price":0,"stop_loss":0,"take_profit":0},"confidence":0.0-1.0,"dry_run":${cfg.dry_run},"executive_summary":"texto","key_reasons":["..."]}`;

let decision = {
  decision:'HOLD',
  final_action:{type:'MARKET',symbol:cfg.symbol||'BTCUSDT',side:'none',quantity_usd:0,price:strat.entry_price||0,stop_loss:strat.stop_loss||0,take_profit:strat.take_profit||0},
  confidence:0,dry_run:cfg.dry_run!==false,
  executive_summary:'API no disponible — operación cancelada por seguridad',
  key_reasons:['API Anthropic no respondió']
};
try {
  const res = await fetch('https://api.anthropic.com/v1/messages', {
    method:'POST',
    headers:{'x-api-key':$env.ANTHROPIC_API_KEY,'anthropic-version':'2023-06-01','Content-Type':'application/json'},
    body: JSON.stringify({model:'claude-opus-4-6',max_tokens:800,messages:[{role:'user',content:prompt}]})
  });
  const d = await res.json();
  const text = d.content[0].text;
  const m = text.match(/\{[\s\S]*\}/);
  if(m) decision = JSON.parse(m[0]);
} catch(e) { decision.executive_summary = `Error: ${e.message}`; }

// Forzar dry_run desde config — seguridad absoluta
decision.dry_run = cfg.dry_run !== false;
decision.final_action = decision.final_action || {};
decision.final_action.symbol = cfg.symbol;
decision.timestamp = new Date().toISOString();
decision.workflow_id = `AT-${Date.now()}`;

return [{json:{agent:'DECISIÓN_FINAL',model:'Claude Opus 4.6',...decision}}];

// EJECUTAR ORDEN BUY
const dec = $input.first().json;
const fa  = dec.final_action || {};

const orderPayload = {
  symbol: fa.symbol,
  side: 'BUY',
  type: fa.type || 'MARKET',
  quoteOrderQty: fa.quantity_usd,
  price: fa.type==='LIMIT' ? fa.price : undefined,
  stopLoss: fa.stop_loss,
  takeProfit: fa.take_profit,
  timestamp: dec.timestamp,
  workflow_id: dec.workflow_id,
  dry_run: dec.dry_run
};

let orderResult = {status:'DRY_RUN',order_id:'SIM-'+Date.now(),filled:false,message:'Modo simulación activo'};

if(!dec.dry_run){
  try {
    const res = await fetch($env.BROKER_ORDER_URL, {
      method:'POST',
      headers:{'Authorization':`Bearer ${$env.BROKER_API_KEY}`,'Content-Type':'application/json'},
      body: JSON.stringify(orderPayload)
    });
    orderResult = await res.json();
  } catch(e){ orderResult = {status:'ERROR',message:e.message,filled:false}; }
} else {
  orderResult.message = `[DRY RUN] BUY $${fa.quantity_usd} de ${fa.symbol} @ ${fa.type} — NO ejecutada`;
}

return [{json:{...dec,order_type:'BUY',order_payload:orderPayload,order_result:orderResult,action_taken:dec.dry_run?'DRY_RUN_BUY':'EXECUTED_BUY'}}];

// EJECUTAR ORDEN SELL
const dec = $input.first().json;
const fa  = dec.final_action || {};

const orderPayload = {
  symbol: fa.symbol,
  side: 'SELL',
  type: fa.type || 'MARKET',
  quoteOrderQty: fa.quantity_usd,
  price: fa.type==='LIMIT' ? fa.price : undefined,
  stopLoss: fa.stop_loss,
  takeProfit: fa.take_profit,
  timestamp: dec.timestamp,
  workflow_id: dec.workflow_id,
  dry_run: dec.dry_run
};

let orderResult = {status:'DRY_RUN',order_id:'SIM-'+Date.now(),filled:false,message:'Modo simulación activo'};

if(!dec.dry_run){
  try {
    const res = await fetch($env.BROKER_ORDER_URL, {
      method:'POST',
      headers:{'Authorization':`Bearer ${$env.BROKER_API_KEY}`,'Content-Type':'application/json'},
      body: JSON.stringify(orderPayload)
    });
    orderResult = await res.json();
  } catch(e){ orderResult = {status:'ERROR',message:e.message,filled:false}; }
} else {
  orderResult.message = `[DRY RUN] SELL $${fa.quantity_usd} de ${fa.symbol} @ ${fa.type} — NO ejecutada`;
}

return [{json:{...dec,order_type:'SELL',order_payload:orderPayload,order_result:orderResult,action_taken:dec.dry_run?'DRY_RUN_SELL':'EXECUTED_SELL'}}];

// NOTIFICADOR — Telegram
const d = $input.first().json;
const fa = d.final_action || {};
const emoji = {BUY:'🟢',SELL:'🔴',HOLD:'⚪'}[d.decision] || '⚪';
const dryTag = d.dry_run ? ' [SIMULACIÓN]' : '';

const lines = [
  `${emoji} *ASESOR DE TRADING${dryTag}*`,
  `\`${d.workflow_id}\` | ${d.timestamp}`,
  ``,
  `*Decisión: ${d.decision}* (confianza: ${((d.confidence||0)*100).toFixed(0)}%)`,
  `Símbolo: ${fa.symbol}`,
  d.decision!=='HOLD' ? `Tamaño: $${fa.quantity_usd} | Tipo: ${fa.type}` : '',
  d.decision!=='HOLD' ? `SL: $${fa.stop_loss} | TP: $${fa.take_profit}` : '',
  ``,
  `*Resumen ejecutivo:*`,
  d.executive_summary,
  ``,
  `*Razones clave:*`,
  (d.key_reasons||[]).map(r=>`• ${r}`).join('\n'),
  ``,
  `*Estado orden:* ${d.order_result?.status||'?'} — ${d.order_result?.message||''}`,
  ``,
  `_Análisis: ${d.vote_summary ? `BUY:${d.vote_summary.buyVotes} SELL:${d.vote_summary.sellVotes} HOLD:${d.vote_summary.holdVotes} conf:${d.vote_summary.avgConf}` : 'N/A'}_`
].filter(l=>l!==undefined);

const text = lines.join('\n').substring(0,4000);

try {
  await fetch(`https://api.telegram.org/bot${$env.TELEGRAM_BOT_TOKEN}/sendMessage`, {
    method:'POST',
    headers:{'Content-Type':'application/json'},
    body: JSON.stringify({chat_id:$env.TELEGRAM_CHAT_ID,text,parse_mode:'Markdown'})
  });
} catch(e){ console.log('Telegram error:', e.message); }

return [{json:{...d,notification_sent:true,notification_text:text}}];

